import{_ as e,o as i,c as s,a2 as a}from"./chunks/framework.CBxkvBm_.js";const h=JSON.parse('{"title":"SPICE Electronics & Circuit Simulation","description":"Native compiler, linter, operating point (.OP), transient (.TRAN), AC small-signal (.AC) solvers, and Modelica/ECAD projections for SPICE netlists in ModelScript.","frontmatter":{"title":"SPICE Electronics & Circuit Simulation","description":"Native compiler, linter, operating point (.OP), transient (.TRAN), AC small-signal (.AC) solvers, and Modelica/ECAD projections for SPICE netlists in ModelScript."},"headers":[],"relativePath":"languages/spice.md","filePath":"languages/spice.md"}'),l={name:"languages/spice.md"};function n(o,t,d,r,c,p){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="spice-electronics-analog-circuit-simulation" tabindex="-1">SPICE Electronics &amp; Analog Circuit Simulation <a class="header-anchor" href="#spice-electronics-analog-circuit-simulation" aria-label="Permalink to &quot;SPICE Electronics &amp; Analog Circuit Simulation&quot;">​</a></h1><p>ModelScript features high-performance native support for <strong>SPICE</strong> (<code>.cir</code>, <code>.sp</code>, <code>.net</code>, <code>.lib</code>) netlists and analog circuit analysis. Engineers can validate electrical schematics, detect topological faults (floating nodes, voltage source loops), execute pure in-WASM circuit simulations, and export to Modelica or ECAD netlist graphs.</p><hr><h2 id="capabilities-supported-formats" tabindex="-1">Capabilities &amp; Supported Formats <a class="header-anchor" href="#capabilities-supported-formats" aria-label="Permalink to &quot;Capabilities &amp; Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Extension</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SPICE Netlist</strong></td><td style="text-align:left;"><code>.cir</code>, <code>.sp</code>, <code>.net</code></td><td style="text-align:left;">Circuit description specifying passive components (R, L, C), active semiconductors (diode, BJT, MOSFET), independent/dependent sources, subcircuits, and simulation directives.</td></tr><tr><td style="text-align:left;"><strong>SPICE Model Library</strong></td><td style="text-align:left;"><code>.lib</code>, <code>.mod</code></td><td style="text-align:left;">Device physics parameters for transistors, diodes, op-amps, and macro-models.</td></tr></tbody></table><h3 id="key-architectural-features" tabindex="-1">Key Architectural Features <a class="header-anchor" href="#key-architectural-features" aria-label="Permalink to &quot;Key Architectural Features&quot;">​</a></h3><ul><li><strong>Engineering Unit Netlist Parser:</strong><ul><li>Robust lexer parsing metric prefixes (<code>f</code>, <code>p</code>, <code>n</code>, <code>u</code>, <code>m</code>, <code>k</code>, <code>meg</code>, <code>g</code>, <code>t</code>), curly brace math expressions <code>{R1 * 2}</code>, line continuations (<code>+</code>), and subcircuit definitions (<code>.SUBCKT</code> / <code>.ENDS</code>).</li><li>Lossless round-trip serializer (<code>serializeSpice()</code>).</li></ul></li><li><strong>Native Numerical Solvers:</strong><ul><li><strong>DC Operating Point (<code>.OP</code>):</strong> Assembles Modified Nodal Analysis (MNA) matrix $\\mathbf{G} \\mathbf{v} = \\mathbf{i}$ with Newton-Raphson iteration for non-linear PN junctions.</li><li><strong>Transient Simulation (<code>.TRAN</code>):</strong> Numerical companion-circuit integration supporting Trapezoidal rule with damping for reactive elements ($L, C$).</li><li><strong>AC Small-Signal Frequency Sweep (<code>.AC</code>):</strong> Complex admittance matrix $\\mathbf{Y}(j\\omega)$ solving decade/octave/linear frequency sweeps and bode response.</li></ul></li><li><strong>Circuit Linter Rules (<code>M7101</code>–<code>M7109</code>):</strong><ul><li>Identifies single-connection floating nodes, parallel ideal voltage sources, cutsets of ideal current sources, non-positive passives, and subcircuit pin mismatches.</li></ul></li><li><strong>Bilateral Modelica &amp; ECAD Projections:</strong><ul><li>Translates SPICE netlists to standard <code>Modelica.Electrical.Analog</code> components.</li><li>Projects to generic <code>NetlistGraph</code> data structures for PCB layout, schematic capture, and Design Rule Checking (DRC).</li></ul></li></ul><hr><h2 id="command-line-interface-msx-spice" tabindex="-1">Command Line Interface (<code>msx spice</code>) <a class="header-anchor" href="#command-line-interface-msx-spice" aria-label="Permalink to &quot;Command Line Interface (\`msx spice\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spice</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [files...] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th><th style="text-align:left;">Key Options</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>inspect</code></strong></td><td style="text-align:left;">Dumps circuit netlist statistics, components, nodes, subcircuits, and directives.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>lint</code></strong></td><td style="text-align:left;">Runs pre-flight electrical topology checks and floating node analysis.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>op</code></strong></td><td style="text-align:left;">Computes DC operating point node voltages and branch currents.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>tran</code></strong></td><td style="text-align:left;">Runs time-domain transient analysis.</td><td style="text-align:left;"><code>--stop=&lt;sec&gt;</code>, <code>--step=&lt;sec&gt;</code>, <code>--out=&lt;file.csv&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>ac</code></strong></td><td style="text-align:left;">Runs small-signal AC frequency sweep.</td><td style="text-align:left;"><code>--fstart=&lt;hz&gt;</code>, <code>--fstop=&lt;hz&gt;</code>, <code>--points=&lt;num&gt;</code>, <code>--type=dec|oct|lin</code>, <code>--out=&lt;file.csv&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-modelica</code></strong></td><td style="text-align:left;">Projects SPICE netlist to standard <code>Modelica.Electrical.Analog</code>.</td><td style="text-align:left;"><code>--out=&lt;file.mo&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-dae</code></strong></td><td style="text-align:left;">Lowers netlist directly into <code>DAEBuilder</code> SoA linear memory arena.</td><td style="text-align:left;">—</td></tr></tbody></table><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Calculate DC bias voltages on all circuit nodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> op</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LowPassFilter.cir</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Simulate transient step response and export trajectory</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tran</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PowerSupply.cir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stop=0.01</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --step=1e-6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=transient.csv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run AC frequency response analysis from 10 Hz to 1 MHz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AudioAmplifier.sp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fstart=10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fstop=1e6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --points=100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=bode.csv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Lint netlist for floating electrical nodes and ground connectivity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SensorFrontEnd.net</span></span></code></pre></div><hr><h2 id="electrical-linters-diagnostic-rules" tabindex="-1">Electrical Linters &amp; Diagnostic Rules <a class="header-anchor" href="#electrical-linters-diagnostic-rules" aria-label="Permalink to &quot;Electrical Linters &amp; Diagnostic Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Identifier</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>M7101</code></strong></td><td style="text-align:left;"><code>floating-node</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Electrical node has only one connected pin; floating circuit hazard.</td></tr><tr><td style="text-align:left;"><strong><code>M7102</code></strong></td><td style="text-align:left;"><code>parallel-voltage-sources</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Loop of ideal voltage sources with zero series impedance violates KVL.</td></tr><tr><td style="text-align:left;"><strong><code>M7103</code></strong></td><td style="text-align:left;"><code>series-current-sources</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Cutset of ideal current sources with unequal branch currents violates KCL.</td></tr><tr><td style="text-align:left;"><strong><code>M7104</code></strong></td><td style="text-align:left;"><code>unresolved-subcircuit</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Subcircuit invocation (<code>X...</code>) references a <code>.SUBCKT</code> name absent from netlist.</td></tr><tr><td style="text-align:left;"><strong><code>M7105</code></strong></td><td style="text-align:left;"><code>invalid-passive-value</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Resistance, capacitance, or inductance is non-positive or non-finite.</td></tr><tr><td style="text-align:left;"><strong><code>M7106</code></strong></td><td style="text-align:left;"><code>transient-step-violation</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Transient maximum step size <code>TSTEP</code> is larger than total simulation duration <code>TSTOP</code>.</td></tr><tr><td style="text-align:left;"><strong><code>M7107</code></strong></td><td style="text-align:left;"><code>duplicate-component-name</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Multiple circuit components share an identical reference designator.</td></tr><tr><td style="text-align:left;"><strong><code>M7108</code></strong></td><td style="text-align:left;"><code>missing-model-definition</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Semiconductor device references a <code>.MODEL</code> card that is not defined.</td></tr><tr><td style="text-align:left;"><strong><code>M7109</code></strong></td><td style="text-align:left;"><code>subcircuit-pin-count-mismatch</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Number of pins on subcircuit instance does not match <code>.SUBCKT</code> header declaration.</td></tr></tbody></table>`,16)])])}const u=e(l,[["render",n]]);export{h as __pageData,u as default};
